"""Tokenizer, syntax tree, and recursive-descent parser for minisql queries."""

import re

from .errors import QueryError

KEYWORDS = frozenset(
    """
    SELECT DISTINCT FROM WHERE GROUP BY HAVING ORDER ASC DESC LIMIT OFFSET
    AS AND OR NOT IS NULL IN BETWEEN LIKE TRUE FALSE
    """.split()
)

# Function name -> (minimum, maximum) number of arguments; None means no limit.
SCALAR_FUNCTIONS = {
    "LOWER": (1, 1),
    "UPPER": (1, 1),
    "LENGTH": (1, 1),
    "ABS": (1, 1),
    "ROUND": (1, 2),
    "COALESCE": (1, None),
}
AGGREGATE_FUNCTIONS = frozenset(["COUNT", "SUM", "AVG", "MIN", "MAX"])

COMPARISON_OPS = frozenset(["=", "!=", "<>", "<", "<=", ">", ">="])

_NUMBER = re.compile(r"[0-9]+(?:\.[0-9]*)?|\.[0-9]+")
_IDENT = re.compile(r"[^\W\d]\w*")
_OPERATORS = (
    "<>", "<=", ">=", "!=", "||",
    "=", "<", ">", "+", "-", "*", "/", "(", ")", ",", ";",
)


# Tokens ----------------------------------------------------------------------


class Token:
    """A lexical token.

    ``kind`` is one of ``"int"``, ``"float"``, ``"string"``, ``"ident"``
    (an unquoted name), ``"quoted"`` (a double-quoted name), ``"keyword"``
    (``value`` upper-cased), ``"op"``, or ``"eof"``.
    """

    __slots__ = ("kind", "value", "start", "end")

    def __init__(self, kind, value, start, end):
        self.kind = kind
        self.value = value
        self.start = start
        self.end = end

    def describe(self):
        if self.kind == "eof":
            return "end of query"
        return repr(self.value) if self.kind != "keyword" else self.value

    def __repr__(self):
        return "Token(%r, %r, %d, %d)" % (self.kind, self.value, self.start, self.end)


def _scan_quoted(sql, start, quote, what):
    """Scan a quoted literal starting at ``start``; return (text, end)."""
    parts = []
    i = start + 1
    while True:
        j = sql.find(quote, i)
        if j < 0:
            raise QueryError("unterminated %s starting at position %d" % (what, start))
        parts.append(sql[i:j])
        if sql.startswith(quote, j + 1):
            parts.append(quote)
            i = j + 2
        else:
            return "".join(parts), j + 1


def tokenize(sql):
    tokens = []
    i = 0
    n = len(sql)
    while i < n:
        c = sql[i]
        if c.isspace():
            i += 1
            continue
        if c == "'":
            text, end = _scan_quoted(sql, i, "'", "string")
            tokens.append(Token("string", text, i, end))
            i = end
            continue
        if c == '"':
            text, end = _scan_quoted(sql, i, '"', "quoted name")
            tokens.append(Token("quoted", text, i, end))
            i = end
            continue
        m = _NUMBER.match(sql, i)
        if m:
            text = m.group()
            end = m.end()
            if end < n and (sql[end].isalnum() or sql[end] == "_"):
                raise QueryError("invalid number at position %d" % i)
            if "." in text:
                tokens.append(Token("float", float(text), i, end))
            else:
                tokens.append(Token("int", int(text), i, end))
            i = end
            continue
        m = _IDENT.match(sql, i)
        if m:
            text = m.group()
            if text.upper() in KEYWORDS:
                tokens.append(Token("keyword", text.upper(), i, m.end()))
            else:
                tokens.append(Token("ident", text, i, m.end()))
            i = m.end()
            continue
        for op in _OPERATORS:
            if sql.startswith(op, i):
                tokens.append(Token("op", op, i, i + len(op)))
                i += len(op)
                break
        else:
            raise QueryError("unexpected character %r at position %d" % (c, i))
    tokens.append(Token("eof", None, n, n))
    return tokens


# Syntax tree -----------------------------------------------------------------


class Node:
    """An expression node.

    ``start`` and ``end`` give the expression's span in the query text;
    ``parens`` is true if the expression was written in parentheses.
    The engine fills in ``kid``, an id shared by structurally equal
    expressions, when it binds the query to a table.
    """

    start = end = 0
    parens = False
    kid = None

    def children(self):
        return ()


class Literal(Node):
    def __init__(self, value):
        self.value = value


class Column(Node):
    index = None

    def __init__(self, name):
        self.name = name


class Unary(Node):
    def __init__(self, op, operand):
        self.op = op
        self.operand = operand

    def children(self):
        return (self.operand,)


class Binary(Node):
    def __init__(self, op, left, right):
        self.op = "!=" if op == "<>" else op
        self.left = left
        self.right = right

    def children(self):
        return (self.left, self.right)


class IsNull(Node):
    def __init__(self, operand, negated):
        self.operand = operand
        self.negated = negated

    def children(self):
        return (self.operand,)


class In(Node):
    def __init__(self, operand, items, negated):
        self.operand = operand
        self.items = items
        self.negated = negated

    def children(self):
        return (self.operand,) + tuple(self.items)


class Between(Node):
    def __init__(self, operand, low, high, negated):
        self.operand = operand
        self.low = low
        self.high = high
        self.negated = negated

    def children(self):
        return (self.operand, self.low, self.high)


class Like(Node):
    def __init__(self, operand, pattern, negated):
        self.operand = operand
        self.pattern = pattern
        self.negated = negated

    def children(self):
        return (self.operand, self.pattern)


class Function(Node):
    def __init__(self, name, args):
        self.name = name
        self.args = args

    def children(self):
        return tuple(self.args)


class Aggregate(Node):
    """An aggregate call; ``arg`` is None for ``COUNT(*)``."""

    def __init__(self, name, arg):
        self.name = name
        self.arg = arg

    def children(self):
        return () if self.arg is None else (self.arg,)


def _span(node, start, end):
    node.start = start
    node.end = end
    return node


class SelectColumn:
    def __init__(self, expr, alias):
        self.expr = expr
        self.alias = alias


class OrderItem:
    def __init__(self, expr, descending):
        self.expr = expr
        self.descending = descending


class Query:
    def __init__(self):
        self.distinct = False
        self.columns = None  # None for SELECT *
        self.table = None
        self.where = None
        self.group_by = []
        self.having = None
        self.order_by = []
        self.limit = None
        self.offset = 0


# Parser ----------------------------------------------------------------------


class Parser:
    def __init__(self, sql):
        self.sql = sql
        self.tokens = tokenize(sql)
        self.pos = 0

    # Token helpers

    def peek(self, offset=0):
        return self.tokens[min(self.pos + offset, len(self.tokens) - 1)]

    def advance(self):
        tok = self.tokens[self.pos]
        if tok.kind != "eof":
            self.pos += 1
        return tok

    def error(self, expected):
        tok = self.peek()
        return QueryError(
            "syntax error at position %d: expected %s, found %s"
            % (tok.start, expected, tok.describe())
        )

    def at_keyword(self, *words):
        tok = self.peek()
        return tok.kind == "keyword" and tok.value in words

    def at_op(self, *ops):
        tok = self.peek()
        return tok.kind == "op" and tok.value in ops

    def accept_keyword(self, word):
        if self.at_keyword(word):
            return self.advance()
        return None

    def accept_op(self, op):
        if self.at_op(op):
            return self.advance()
        return None

    def expect_keyword(self, word):
        if not self.at_keyword(word):
            raise self.error(word)
        return self.advance()

    def expect_op(self, op):
        if not self.at_op(op):
            raise self.error("'%s'" % op)
        return self.advance()

    def at_name(self):
        return self.peek().kind in ("ident", "quoted")

    def parse_name(self, what="a name"):
        tok = self.peek()
        if tok.kind in ("ident", "quoted"):
            return self.advance().value
        if tok.kind == "keyword":
            raise QueryError(
                "syntax error at position %d: keyword %s can't be used as a name"
                " (put it in double quotes)" % (tok.start, tok.value)
            )
        raise self.error(what)

    def parse_unsigned_int(self):
        tok = self.peek()
        if tok.kind != "int":
            raise self.error("an integer")
        return self.advance().value

    # Query

    def parse_query(self):
        query = Query()
        self.expect_keyword("SELECT")
        query.distinct = self.accept_keyword("DISTINCT") is not None
        if self.accept_op("*"):
            query.columns = None
        else:
            query.columns = [self.parse_column()]
            while self.accept_op(","):
                query.columns.append(self.parse_column())
        self.expect_keyword("FROM")
        query.table = self.parse_name("a table name")
        if self.accept_keyword("WHERE"):
            query.where = self.parse_expr()
        if self.accept_keyword("GROUP"):
            self.expect_keyword("BY")
            query.group_by = [self.parse_expr()]
            while self.accept_op(","):
                query.group_by.append(self.parse_expr())
        if self.accept_keyword("HAVING"):
            query.having = self.parse_expr()
        if self.accept_keyword("ORDER"):
            self.expect_keyword("BY")
            query.order_by = [self.parse_order_item()]
            while self.accept_op(","):
                query.order_by.append(self.parse_order_item())
        if self.accept_keyword("LIMIT"):
            query.limit = self.parse_unsigned_int()
            if self.accept_keyword("OFFSET"):
                query.offset = self.parse_unsigned_int()
        self.accept_op(";")
        if self.peek().kind != "eof":
            raise self.error("end of query")
        return query

    def parse_column(self):
        expr = self.parse_expr()
        alias = None
        if self.accept_keyword("AS"):
            alias = self.parse_name("a column alias")
        elif self.at_name():
            alias = self.parse_name()
        return SelectColumn(expr, alias)

    def parse_order_item(self):
        expr = self.parse_expr()
        descending = False
        if self.accept_keyword("DESC"):
            descending = True
        else:
            self.accept_keyword("ASC")
        return OrderItem(expr, descending)

    # Expressions, lowest precedence first

    def parse_expr(self):
        return self.parse_or()

    def parse_or(self):
        left = self.parse_and()
        while self.accept_keyword("OR"):
            right = self.parse_and()
            left = _span(Binary("OR", left, right), left.start, right.end)
        return left

    def parse_and(self):
        left = self.parse_not()
        while self.accept_keyword("AND"):
            right = self.parse_not()
            left = _span(Binary("AND", left, right), left.start, right.end)
        return left

    def parse_not(self):
        tok = self.accept_keyword("NOT")
        if tok:
            operand = self.parse_not()
            return _span(Unary("NOT", operand), tok.start, operand.end)
        return self.parse_comparison()

    def parse_comparison(self):
        left = self.parse_additive()
        while True:
            tok = self.peek()
            if tok.kind == "op" and tok.value in COMPARISON_OPS:
                self.advance()
                right = self.parse_additive()
                left = _span(Binary(tok.value, left, right), left.start, right.end)
                continue
            if self.accept_keyword("IS"):
                negated = self.accept_keyword("NOT") is not None
                end = self.expect_keyword("NULL").end
                left = _span(IsNull(left, negated), left.start, end)
                continue
            negated = False
            if self.at_keyword("NOT"):
                following = self.peek(1)
                if following.kind == "keyword" and following.value in ("IN", "BETWEEN", "LIKE"):
                    self.advance()
                    negated = True
            if self.accept_keyword("IN"):
                self.expect_op("(")
                items = [self.parse_expr()]
                while self.accept_op(","):
                    items.append(self.parse_expr())
                end = self.expect_op(")").end
                left = _span(In(left, items, negated), left.start, end)
            elif self.accept_keyword("BETWEEN"):
                low = self.parse_additive()
                self.expect_keyword("AND")
                high = self.parse_additive()
                left = _span(Between(left, low, high, negated), left.start, high.end)
            elif self.accept_keyword("LIKE"):
                pattern = self.parse_additive()
                left = _span(Like(left, pattern, negated), left.start, pattern.end)
            else:
                return left

    def parse_additive(self):
        left = self.parse_multiplicative()
        while self.at_op("+", "-", "||"):
            op = self.advance().value
            right = self.parse_multiplicative()
            left = _span(Binary(op, left, right), left.start, right.end)
        return left

    def parse_multiplicative(self):
        left = self.parse_unary()
        while self.at_op("*", "/"):
            op = self.advance().value
            right = self.parse_unary()
            left = _span(Binary(op, left, right), left.start, right.end)
        return left

    def parse_unary(self):
        tok = self.accept_op("-")
        if tok:
            operand = self.parse_unary()
            return _span(Unary("-", operand), tok.start, operand.end)
        return self.parse_primary()

    def parse_primary(self):
        tok = self.peek()
        if tok.kind in ("int", "float", "string"):
            self.advance()
            return _span(Literal(tok.value), tok.start, tok.end)
        if tok.kind == "keyword" and tok.value in ("NULL", "TRUE", "FALSE"):
            self.advance()
            value = {"NULL": None, "TRUE": True, "FALSE": False}[tok.value]
            return _span(Literal(value), tok.start, tok.end)
        if tok.kind == "ident" and self.peek(1).kind == "op" and self.peek(1).value == "(":
            return self.parse_call()
        if tok.kind in ("ident", "quoted"):
            self.advance()
            return _span(Column(tok.value), tok.start, tok.end)
        if tok.kind == "op" and tok.value == "(":
            self.advance()
            expr = self.parse_expr()
            end = self.expect_op(")").end
            expr.parens = True
            return _span(expr, tok.start, end)
        if tok.kind == "keyword":
            raise QueryError(
                "syntax error at position %d: expected an expression, found keyword %s"
                % (tok.start, tok.value)
            )
        raise self.error("an expression")

    def parse_call(self):
        name_tok = self.advance()
        name = name_tok.value.upper()
        self.expect_op("(")
        star = False
        args = []
        if self.at_op("*") and self.peek(1).kind == "op" and self.peek(1).value == ")":
            self.advance()
            star = True
        elif not self.at_op(")"):
            args.append(self.parse_expr())
            while self.accept_op(","):
                args.append(self.parse_expr())
        end = self.expect_op(")").end

        if name in AGGREGATE_FUNCTIONS:
            if star:
                if name != "COUNT":
                    raise QueryError("%s(*) is not allowed; only COUNT(*) is" % name)
                return _span(Aggregate(name, None), name_tok.start, end)
            if len(args) != 1:
                raise QueryError(
                    "%s takes 1 argument, got %d" % (name, len(args))
                )
            return _span(Aggregate(name, args[0]), name_tok.start, end)

        if name not in SCALAR_FUNCTIONS:
            raise QueryError("unknown function %s" % name_tok.value)
        if star:
            raise QueryError("%s(*) is not allowed" % name)
        low, high = SCALAR_FUNCTIONS[name]
        if len(args) < low or (high is not None and len(args) > high):
            if high is None:
                expected = "at least %d" % low
            elif low == high:
                expected = str(low)
            else:
                expected = "%d to %d" % (low, high)
            raise QueryError(
                "%s takes %s argument%s, got %d"
                % (name, expected, "" if expected == "1" else "s", len(args))
            )
        return _span(Function(name, args), name_tok.start, end)


def parse(sql):
    """Parse ``sql`` into a :class:`Query`."""
    return Parser(sql).parse_query()

