            return x.upper()
        return len(x)
    if not is_number(x):
        raise QueryError("%s needs a number, got %s" % (name, type_name(x)))
    if name == "ABS":
        return abs(x)
    # ROUND
    digits = None
    if len(args) == 2:
        digits = args[1]
        if not isinstance(digits, int) or isinstance(digits, bool):
            raise QueryError("ROUND needs an integer number of digits, got %r" % (digits,))
    return sql_round(x, digits)


_EVALUATORS = {
    Literal: _eval_literal,
    Column: _eval_column,
    Aggregate: _eval_aggregate,
    Unary: _eval_unary,
    Binary: _eval_binary,
    IsNull: _eval_is_null,
    In: _eval_in,
    Between: _eval_between,
    Like: _eval_like,
    Function: _eval_function,
}


# Binding and checking --------------------------------------------------------


class Binder:
    """Resolves column names and gives structurally equal expressions equal kids."""

    def __init__(self, table):
        self.table = table
        self._kids = {}

    def bind(self, node):
        for child in node.children():
            self.bind(child)
        if isinstance(node, Column):
            node.index = self.table.resolve(node.name)
        node.kid = self._kids.setdefault(self._shape(node), len(self._kids))
        return node

    @staticmethod
    def _shape(node):
        kids = tuple(child.kid for child in node.children())
        if isinstance(node, Literal):
            return ("literal", type_name(node.value), type(node.value), node.value)
        if isinstance(node, Column):
            return ("column", node.index)
        if isinstance(node, (Unary, Binary)):
            return (type(node).__name__, node.op, kids)
        if isinstance(node, (IsNull, In, Between, Like)):
            return (type(node).__name__, node.negated, kids)
        if isinstance(node, Aggregate):
            return ("aggregate", node.name, node.arg is None, kids)
        return ("function", node.name, kids)


def walk(node):
    yield node
    for child in node.children():
        for descendant in walk(child):
            yield descendant


def has_aggregate(node):
    return any(isinstance(n, Aggregate) for n in walk(node))


def forbid_aggregates(node, where):
    for n in walk(node):
        if isinstance(n, Aggregate):
            raise QueryError("aggregate %s can't be used in %s" % (n.name, where))


def check_grouped(node, group_kids):
    """Check that ``node`` can be evaluated once per group."""
    if node.kid in group_kids:
        return
    if isinstance(node, Aggregate):
        if node.arg is not None:
            forbid_aggregates(node.arg, "another aggregate")
        return
    if isinstance(node, Column):
        raise QueryError(
            "column %s must appear in GROUP BY or be used in an aggregate"
            % _quote(node.name)
        )
    for child in node.children():
        check_grouped(child, group_kids)


# Execution -------------------------------------------------------------------


def execute(query, sql, directory):
    table = load_table(directory, query.table)
    binder = Binder(table)

    # Output columns.
    if query.columns is None:
        exprs = []
        for index, name in enumerate(table.header):
            column = Column(name)
            column.index = index
            column.kid = binder._kids.setdefault(("column", index), len(binder._kids))
            exprs.append(column)
        names = list(table.header)
    else:
        exprs = []
        names = []
        for column in query.columns:
            expr = binder.bind(column.expr)
            exprs.append(expr)
            if column.alias is not None:
                names.append(column.alias)
            elif isinstance(expr, Column):
                names.append(table.header[expr.index])
            else:
                names.append(sql[expr.start:expr.end])

    where = binder.bind(query.where) if query.where is not None else None
    group_by = [binder.bind(expr) for expr in query.group_by]
    having = binder.bind(query.having) if query.having is not None else None

    # ORDER BY items: ("output", column number) or ("expr", bound expression).
    lowered_names = [name.lower() for name in names]
    order = []
    for item in query.order_by:
        expr = item.expr
        if isinstance(expr, Column) and not expr.parens and expr.name.lower() in lowered_names:
            order.append(("output", lowered_names.index(expr.name.lower()), item.descending))
        elif (
            isinstance(expr, Literal)
            and not expr.parens
            and is_number(expr.value)
            and isinstance(expr.value, int)
        ):
            if not 1 <= expr.value <= len(names):
                raise QueryError(
                    "ORDER BY column number %d is out of range (1 to %d)"
                    % (expr.value, len(names))
                )
            order.append(("output", expr.value - 1, item.descending))
        else:
            order.append(("expr", binder.bind(expr), item.descending))
    order_exprs = [target for kind, target, _ in order if kind == "expr"]

    # Checks.
    if where is not None:
        forbid_aggregates(where, "WHERE")
    for expr in group_by:
        forbid_aggregates(expr, "GROUP BY")
    grouped = bool(group_by) or any(
        has_aggregate(expr)
        for expr in exprs + order_exprs + ([having] if having is not None else [])
    )
    if grouped:
        group_kids = {expr.kid for expr in group_by}
        for expr in exprs + order_exprs + ([having] if having is not None else []):
            check_grouped(expr, group_kids)

    # Filter.
    rows = table.rows
    if where is not None:
        rows = [row for row in rows if require_boolean(RowEnv(row).eval(where), "WHERE") is True]

    # Environments: one per output row.
    if grouped:
        groups = {}
        for row in rows:
            env = RowEnv(row)
            values = [env.eval(expr) for expr in group_by]
            key = tuple(group_key(v) for v in values)
            if key not in groups:
                groups[key] = (values, [])
            groups[key][1].append(row)
        if not group_by and not groups:
            groups[()] = ([], [])
        envs = [
            GroupEnv({expr.kid: value for expr, value in zip(group_by, values)}, group_rows)
            for values, group_rows in groups.values()
        ]
    else:
        envs = [RowEnv(row) for row in rows]
    if having is not None:
        envs = [env for env in envs if require_boolean(env.eval(having), "HAVING") is True]

    # Project, computing sort keys alongside.
    results = []
    for env in envs:
        out = tuple(env.eval(expr) for expr in exprs)
        sort_key = [
            (out[target] if kind == "output" else env.eval(target), descending)
            for kind, target, descending in order
        ]
        results.append((out, sort_key))

    if query.distinct:
        seen = set()
        unique = []
        for out, sort_key in results:
            key = tuple(group_key(v) for v in out)
            if key not in seen:
                seen.add(key)
                unique.append((out, sort_key))
        results = unique

    if order:
        results.sort(key=functools.cmp_to_key(_compare_sort_keys))

    output = [out for out, _ in results]
    start = query.offset
    stop = None if query.limit is None else start + query.limit
    return Result(names, output[start:stop])


def _compare_sort_keys(a, b):
    for (x, descending), (y, _) in zip(a[1], b[1]):
        if x is None and y is None:
            c = 0
        elif x is None:
            c = -1
        elif y is None:
            c = 1
        else:
            c = compare(x, y)
        if descending:
            c = -c
        if c:
            return c
    return 0

