"""Loading tables, binding queries to them, and evaluating queries."""

import csv
import decimal
import functools
import math
import os
import re

from .errors import QueryError
from .parser import (
    Aggregate,
    Between,
    Binary,
    Column,
    Function,
    In,
    IsNull,
    Like,
    Literal,
    Unary,
)


class Result:
    """The result of a query: ``columns`` (names) and ``rows`` (tuples)."""

    __slots__ = ("columns", "rows")

    def __init__(self, columns, rows):
        self.columns = columns
        self.rows = rows

    def __repr__(self):
        return "Result(columns=%r, rows=%r)" % (self.columns, self.rows)

    def __eq__(self, other):
        if not isinstance(other, Result):
            return NotImplemented
        return self.columns == other.columns and self.rows == other.rows


# Tables ----------------------------------------------------------------------

_INTEGER = re.compile(r"-?[0-9]+")
_DECIMAL = re.compile(r"-?[0-9]+\.[0-9]*|-?[0-9]*\.[0-9]+")


def convert_field(text):
    if text == "":
        return None
    if _INTEGER.fullmatch(text):
        return int(text)
    if _DECIMAL.fullmatch(text):
        return float(text)
    return text


class Table:
    def __init__(self, name, header, rows):
        self.name = name
        self.header = header
        self.rows = rows
        self._lookup = {}
        for index, column in enumerate(header):
            self._lookup.setdefault(column.lower(), []).append(index)

    def resolve(self, name):
        indexes = self._lookup.get(name.lower(), [])
        if not indexes:
            raise QueryError("unknown column %s in table %s" % (_quote(name), self.name))
        if len(indexes) > 1:
            raise QueryError("ambiguous column %s in table %s" % (_quote(name), self.name))
        return indexes[0]


def _quote(name):
    return '"%s"' % name.replace('"', '""')


def load_table(directory, name):
    seps = {"/", "\0", os.sep, os.altsep} - {None}
    if not name or any(sep in name for sep in seps):
        raise QueryError("invalid table name %s" % _quote(name))
    path = os.path.join(os.fspath(directory), name + ".csv")
    if not os.path.isfile(path):
        raise QueryError("unknown table %s (no file %s)" % (name, path))
    try:
        with open(path, newline="", encoding="utf-8-sig") as f:
            reader = csv.reader(f)
            header = next(reader, None)
            if header is None:
                raise QueryError("table %s has no header line" % name)
            rows = []
            for record in reader:
                if not record:
                    continue  # blank line
                if len(record) != len(header):
                    raise QueryError(
                        "table %s, line %d: expected %d fields, found %d"
                        % (name, reader.line_num, len(header), len(record))
                    )
                rows.append([convert_field(field) for field in record])
    except (OSError, UnicodeDecodeError, csv.Error) as e:
        raise QueryError("can't read table %s: %s" % (name, e)) from None
    return Table(name, header, rows)


# Values ----------------------------------------------------------------------


def is_number(value):
    return isinstance(value, (int, float)) and not isinstance(value, bool)


def type_name(value):
    if value is None:
        return "NULL"
    if isinstance(value, bool):
        return "boolean"
    if is_number(value):
        return "number"
    return "string"


def compare(a, b):
    """Compare two non-NULL values; return -1, 0, or 1."""
    ta, tb = type_name(a), type_name(b)
    if ta != tb:
        raise QueryError("can't compare %s with %s" % (ta, tb))
    return (a > b) - (a < b)


def to_text(value):
    if isinstance(value, bool):
        return "true" if value else "false"
    return str(value)


def group_key(value):
    """A hashable key under which equal values are equal (and 1 != TRUE)."""
    return (type_name(value), value)


def require_boolean(value, what):
    if value is not None and not isinstance(value, bool):
        raise QueryError("%s needs a boolean, got %s" % (what, type_name(value)))
    return value


def arithmetic(op, a, b):
    if a is None or b is None:
        return None
    if not (is_number(a) and is_number(b)):
        raise QueryError("can't apply %s to %s and %s" % (op, type_name(a), type_name(b)))
    if op == "+":
        result = a + b
    elif op == "-":
        result = a - b
    elif op == "*":
        result = a * b
    else:
        if b == 0:
            return None
        return float(a / b)
    if isinstance(a, int) and isinstance(b, int):
        return result
    return float(result)


def three_valued_and(a, b):
    if a is False or b is False:
        return False
    if a is None or b is None:
        return None
    return True


def three_valued_or(a, b):
    if a is True or b is True:
        return True
    if a is None or b is None:
        return None
    return False


def negate(value, negated):
    if negated and value is not None:
        return not value
    return value


@functools.lru_cache(maxsize=256)
def like_regex(pattern):
    parts = []
    for c in pattern:
        if c == "%":
            parts.append(".*")
        elif c == "_":
            parts.append(".")
        else:
            parts.append(re.escape(c))
    return re.compile("".join(parts), re.DOTALL)


def sql_round(x, digits):
    """Round ``x`` half away from zero (to an int if ``digits`` is None)."""
    if isinstance(x, float) and not math.isfinite(x):
        if digits is None:
            raise QueryError("can't round %r to an integer" % x)
        return x
    if digits is None and isinstance(x, int):
        return x
    d = decimal.Decimal(repr(x)) if isinstance(x, float) else decimal.Decimal(x)
    places = 0 if digits is None else digits
    if d.as_tuple().exponent >= -places:
        # Already has no more than ``places`` decimal places.
        return int(d) if digits is None else float(x)
    try:
        with decimal.localcontext() as ctx:
            ctx.prec = len(d.as_tuple().digits) + 2
            rounded = d.quantize(
                decimal.Decimal(1).scaleb(-places), rounding=decimal.ROUND_HALF_UP
            )
    except decimal.DecimalException:
        raise QueryError("ROUND: number of digits out of range") from None
    return int(rounded) if digits is None else float(rounded)


# Evaluation ------------------------------------------------------------------


class RowEnv:
    """Evaluates expressions against one input row."""

    def __init__(self, row):
        self.row = row

    def eval(self, node):
        return _EVALUATORS[type(node)](node, self)

    def column(self, node):
        return self.row[node.index]

    def aggregate(self, node):
        raise QueryError("aggregate %s can't be used here" % node.name)


class GroupEnv:
    """Evaluates expressions against a group of input rows."""

    def __init__(self, key_values, rows):
        self.key_values = key_values  # kid of a GROUP BY expression -> value
        self.rows = rows
        self._aggregates = {}

    def eval(self, node):
        if node.kid in self.key_values:
            return self.key_values[node.kid]
        return _EVALUATORS[type(node)](node, self)

    def column(self, node):
        # Ruled out when the query is checked.
        raise QueryError(
            "column %s must appear in GROUP BY or be used in an aggregate"
            % _quote(node.name)
        )

    def aggregate(self, node):
        if node.kid not in self._aggregates:
            self._aggregates[node.kid] = compute_aggregate(node, self.rows)
        return self._aggregates[node.kid]


def compute_aggregate(node, rows):
    if node.arg is None:
        return len(rows)
    values = [RowEnv(row).eval(node.arg) for row in rows]
    values = [v for v in values if v is not None]
    if node.name == "COUNT":
        return len(values)
    if not values:
        return None
    if node.name in ("SUM", "AVG"):
        for v in values:
            if not is_number(v):
                raise QueryError("%s needs numbers, got %s" % (node.name, type_name(v)))
        total = sum(values)
        if node.name == "AVG":
            return float(total / len(values))
        return total if all(isinstance(v, int) for v in values) else float(total)
    best = values[0]
    sign = -1 if node.name == "MIN" else 1
    for v in values[1:]:
        if compare(v, best) * sign > 0:
            best = v
    return best


def _eval_literal(node, env):
    return node.value


def _eval_column(node, env):
    return env.column(node)


def _eval_aggregate(node, env):
    return env.aggregate(node)


def _eval_unary(node, env):
    value = env.eval(node.operand)
    if value is None:
        return None
    if node.op == "NOT":
        return not require_boolean(value, "NOT")
    if not is_number(value):
        raise QueryError("can't negate %s" % type_name(value))
    return -value


def _eval_binary(node, env):
    op = node.op
    left = env.eval(node.left)
    right = env.eval(node.right)
    if op == "AND":
        return three_valued_and(require_boolean(left, "AND"), require_boolean(right, "AND"))
    if op == "OR":
        return three_valued_or(require_boolean(left, "OR"), require_boolean(right, "OR"))
    if left is None or right is None:
        return None
    if op == "||":
        return to_text(left) + to_text(right)
    if op in ("+", "-", "*", "/"):
        return arithmetic(op, left, right)
    c = compare(left, right)
    if op == "=":
        return c == 0
    if op == "!=":
        return c != 0
    if op == "<":
        return c < 0
    if op == "<=":
        return c <= 0
    if op == ">":
        return c > 0
    return c >= 0


def _eval_is_null(node, env):
    return (env.eval(node.operand) is None) != node.negated


def _eval_in(node, env):
    value = env.eval(node.operand)
    found = False
    saw_null = value is None
    for item in node.items:
        item_value = env.eval(item)
        if item_value is None:
            saw_null = True
        elif value is not None and compare(value, item_value) == 0:
            found = True
    result = True if found else (None if saw_null else False)
    return negate(result, node.negated)


def _less_or_equal(a, b):
    if a is None or b is None:
        return None
    return compare(a, b) <= 0


def _eval_between(node, env):
    value = env.eval(node.operand)
    low = env.eval(node.low)
    high = env.eval(node.high)
    result = three_valued_and(_less_or_equal(low, value), _less_or_equal(value, high))
    return negate(result, node.negated)


def _eval_like(node, env):
    value = env.eval(node.operand)
