"""Command line: ``python -m minisql QUERY [--dir DIR]``."""

import argparse
import csv
import sys

from . import QueryError, run


def format_value(value):
    if value is None:
        return ""
    if value is True:
        return "true"
    if value is False:
        return "false"
    return value


def main(argv=None):
    parser = argparse.ArgumentParser(
        prog="python -m minisql",
        description="Run a SQL SELECT query against a directory of CSV files.",
    )
    parser.add_argument("query", metavar="QUERY", help="the SELECT query to run")
    parser.add_argument(
        "--dir", default=".", metavar="DIR",
        help="directory containing the CSV files (default: current directory)",
    )
    args = parser.parse_args(argv)

    try:
        result = run(args.query, args.dir)
    except QueryError as e:
        print(e, file=sys.stderr)
        return 1

    if hasattr(sys.stdout, "reconfigure"):
        sys.stdout.reconfigure(newline="")  # csv writes its own line endings
    writer = csv.writer(sys.stdout)
    writer.writerow(result.columns)
    for row in result.rows:
        writer.writerow([format_value(value) for value in row])
    return 0


if __name__ == "__main__":
    sys.exit(main())

